/* Native projectile descriptors, parser and physical allocator ownership. */
#define Q3_ITEM_OWNER_ONLY
#include "bot_item_config_regression.c"
static int scalarProof;
static const char *scalars="flags 117 gravity 0.5 damage 25 radius 96 visdamage 30 damagetype 3 healthinc 4 push 8 detonation 1.25 bounce 0.125 bouncefric 0.875 bouncestop 0.5";
static void ProjectileCase(int length,int last){char model[MAX_STRINGFIELD],text[2048];source_t *source;struct {unsigned int before;projectileinfo_t info;unsigned int after;} record;int i;Begin();memset(&record,0,sizeof(record));record.before=0x12345678U;record.after=0x87654321U;for(i=0;i<length;i++)model[i]=(char)('a'+i%26);model[length<0?0:length]=0;if(length<0)snprintf(text,sizeof(text),"{ name \"Native\" %s }",scalars);else if(last)snprintf(text,sizeof(text),"{ name \"Native\" %s model \"%s\" }",scalars,model);else snprintf(text,sizeof(text),"{ name \"Native\" model \"%s\" %s }",model,scalars);Attempt(text);source=LoadSourceFile("native.c");Check(source&&ReadStructure(source,&projectileinfo_struct,(char *)&record.info)&&!PC_SourceHasError(source),"actual native projectile structure parses");Check(!strcmp(record.info.name,"Native")&&(scalarProof||!strcmp(record.info.model,length<0?"":model)),"projectile model occupies its native field, independent of numeric field order");Check(record.info.flags==117&&record.info.gravity==0.5f&&record.info.damage==25&&record.info.radius==96&&record.info.visdamage==30&&record.info.damagetype==3&&record.info.healthinc==4&&record.info.push==8&&record.info.detonation==1.25f&&record.info.bounce==0.125f&&record.info.bouncefric==0.875f&&record.info.bouncestop==0.5f,"every native projectile scalar survives model parsing");Check(record.before==0x12345678U&&record.after==0x87654321U,"native structure parse retains both physical canaries");FreeSource(source);Check(!heapLive&&!hunkLive&&!numtokens&&!errors&&!warnings,"projectile source and tokens physically release");End();}
int main(int argc,char **argv){int lengths[]={0,1,13,71,72,79},i,last;if(argc>1){if(atoi(argv[1])==0)ProjectileCase(13,0);else if(atoi(argv[1])==1){scalarProof=1;ProjectileCase(79,1);}else ProjectileCase(-1,0);return 0;}ProjectileCase(-1,0);for(last=0;last<2;last++)for(i=0;i<6;i++)ProjectileCase(lengths[i],last);puts("Actual native projectile model/scalars/order, boundary strings and physical parser ownership pass (issue #48)");return 0;}
